  'The next regular target continues from the last included workout.': '下一个常规目标从上一次计入的训练继续。',
  'Deload routine': '减载训练日',
  'Its workouts do not count toward progression. They still show in history and statistics.': '它的训练不计入进阶，但仍会显示在历史记录和统计中。',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': '减载训练日按这里设定的数值开始，因此上面的进阶方式对它不适用。',
  'Linear progression': '线性进阶',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': '双重进阶',
  'Add time': '增加时间',
  'Targets stay where you set them.': '目标保持你设定的样子。',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': '每组都完成全部次数，重量就上调。反复未完成则触发减载。',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': '两组常规组，再加最后一组做到力竭。最后一组超过目标就加重（次数翻倍则加倍）。失败一次回落 10 %。',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': '在同一重量下把次数从下限做到上限。每组都做到上限就加重，次数回到下限。',
  'Hold every set for the full duration and the target goes up.': '每组都保持满时长，目标就上调。',
  'Nothing logged yet, so this session sets the baseline.': '还没有记录，这次训练就是基准。',
  'Held every set for the full time. Target goes up by {0}s.': '每组都撑满了时长。目标增加 {0} 秒。',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '连续 {0} 次没撑满。回到 {1} 秒，重新积累。',
  'Came up short last time. Same target again.': '上次差了一点。再来一次同样的目标。',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': '每组都做到次数上限。加 {0} {1}，次数回到 {2}。',
  'Stuck for {0} sessions. Deload to {1} {2}.': '已停滞 {0} 次训练。减载到 {1} {2}。',
  'Same weight, aim for {0} reps this time.': '同样的重量，这次目标 {0} 次。',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': '最后一组做了 {0} 次，是目标的两倍！加倍上调 {1} {2}。',
  'Every rep last time. {0} {1} more.': '上次每次都完成了。加 {0} {1}。',
  'Every rep last time. {0} {1} less help.': '上次每次都完成了。辅助减少 {0} {1}。',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': '每组都做到次数上限。辅助减少 {0} {1}，次数回到 {2}。',
  'Missed reps. {0} {1} of help while you build back up.': '次数没做够。先用 {0} {1} 辅助，慢慢练回来。',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': '已停滞 {0} 次。回到 {1} {2} 辅助，再重新往上加。',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': '连续 {0} 次没做够次数。回到 {1} {2}，重新往上练。',
