  // --- AI Coach on the phone ---
  '(saved)': '（已保存）',
  'AI Coach': 'AI 教练',
  'API key': 'API 密钥',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs with your own API key, it never changes anything without your say-so, and it is off until you turn it on.': '一个能为你设计计划并根据你实际记录进行调整的 AI 教练。它使用你自己的 API 密钥运行，未经你同意不会更改任何内容，并且在你开启之前保持关闭。',
  'Bring my own API key': '使用我自己的 API 密钥',
  'Could not reach the provider: {0}': '无法连接到提供商：{0}',
  'Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted Gains”: your server can reach an http:// model on its own network.': 'Android 会阻止应用发起未加密的 http:// 连接，所以这部手机只能连接 https:// 端点。请在它前面加一层 HTTPS（Tailscale 或反向代理），或选择“使用我自托管的 Gains”：你的服务器可以访问它自己网络中的 http:// 模型。',
  'Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.': '每个请求都会用你的密钥直接发送到 {0}。其他人看不到，费用由你承担。',
