  'Have a look at my training and tell me what you would change.': '看看我的训练，告诉我你会改什么。',
  'Here is what I am working with:': '这是我的情况：',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': '你好，我是你的教练。我根据你的回答制定计划，再根据你实际记录的内容调整。你不点头，什么都不会变。',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': '我全部看了一遍，目前没有想改的地方。继续保持，再练几次后再来问我。',
  'I understand, let’s go': '明白了，开始吧',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': '已导入！{0} 个训练日已加入你的计划，本周也安排好了。下次训练见。',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': '已导入！{0} 个训练日已加入你的计划。本周安排不变，你想什么时候排都行。',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': '它根据几个回答设计你的计划，并根据你的实际记录进行调整。未经你同意它不会更改任何内容，每项更改都可以撤销。',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': '训练计划、动作、组数和次数、你的每周日程以及进阶设置。',
  'Your logged training': '你记录的训练',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes. Also your weekly check-in: how training felt, how you slept, and your note.': '你在复盘周期内记录的各组数据：重量、次数、时间、强度评分、每次训练的时长，以及你的训练备注。还有你的每周回顾：训练感觉如何、睡得怎样，以及你的备注。',
  'Weigh-ins from the same window, and your goal weight if you set one.': '同一时段的称重记录，以及你设定的目标体重（如有）。',
