  '{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '此设备在未登录时记录了 {0} 次训练和 {1} 次体重。把它们加入你的个人资料，或保持个人资料与服务器上的完全一致。',
