  // --- triple progression (issue #179) ---
  'Triple progression': '三重进阶',
  'Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.': '次数先升到区间上限，然后加一组，直到你设定的最多组数。全部到顶后加重量，回到最初的组数和次数。',
