  'Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.': '全部 {0} 组都到了区间上限。加 {1} {2}，回到 {3} 组 × {4} 次。',
  'Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.': '全部 {0} 组都到了区间上限。少 {1} {2} 助力，回到 {3} 组 × {4} 次。',
  'Short of the target, but more reps than before. Same sets and reps again.': '没完全达标，但次数比之前多。同样的组数和次数再来一次。',
